/**
 * @method
 * @name scwin.downloadFile_direct
 * @author Inswave
 * @date 2026. 09. 29
 * @param _contn_id
 * @returns
 * @hidden N
*/
scwin.downloadFile_direct = async function (_contn_id) {
    /* sdd-asis-lifecycle:begin downloadFile_direct — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fm = (document.downloadForm || { elements: [] });
    if (_contn_id === '1') {
        $c.util.getComponent("dma_printReq").set("orgnFileNm", "사업자등록증(서울사옥).jpg");
    } else {
        if (_contn_id === '2') {
            $c.util.getComponent("dma_printReq").set("orgnFileNm", "통장사본_채권상장수수료.jpg");
        } else {
            if (_contn_id === '3') {
                $c.util.getComponent("dma_printReq").set("orgnFileNm", "통장사본_채권연부과금.jpg");
            }
        }
    }
    fm.action = '/upload/downloadFile.do';
    $c.util.getComponent("dma_printReq").set("method", 'downloadFileAttach');
    await scwin.tx_downloadFile_direct();
    /* sdd-asis-lifecycle:end */
};


